function pairMinSum(nums: number[]): number {
  const used = new Array(nums.length).fill(false);
  const go = (): number => {
    const i = used.indexOf(false);
    if (i === -1) return 0;
    used[i] = true;
    let best = -Infinity;
    for (let j = i + 1; j < nums.length; j++) {
      if (used[j]) continue;
      used[j] = true;
      best = Math.max(best, Math.min(nums[i], nums[j]) + go());
      used[j] = false;
    }
    used[i] = false;
    return best;
  };
  return go();
}

