function pairMinSum(nums: number[]): number {
  const OFF = 10000;
  const count = new Array(2 * OFF + 1).fill(0);
  for (const x of nums) count[x + OFF]++;
  let total = 0, pos = 0;
  for (let v = 0; v < count.length; v++) {
    for (let c = 0; c < count[v]; c++, pos++) {
      if (pos % 2 === 0) total += v - OFF;
    }
  }
  return total;
}

