class Solution:
    def pairMinSum(self, nums: List[int]) -> int:
        OFF = 10000
        count = [0] * (2 * OFF + 1)
        for x in nums:
            count[x + OFF] += 1
        total = pos = 0
        for v, c in enumerate(count):
            for _ in range(c):
                if pos % 2 == 0:
                    total += v - OFF
                pos += 1
        return total

